let _pass = 0;
let _fail = 0;
function _test(num: number, got: any, expected: any) {
  const passed = got === expected;
  console.log('---------------------');
  console.log('Test ' + num + ':');
  console.log('Output: ' + got);
  console.log(passed ? 'Pass' : 'Fail');
  if (passed) _pass++; else _fail++;
}
_test(1, typeof overpriced.title, 'string');
_test(2, typeof overpriced.views, 'number');
_test(3, typeof overpriced.adFree, 'boolean');
_test(4, 'title' in overpriced && 'views' in overpriced && 'adFree' in overpriced, true);
_test(5, Object.keys(overpriced).length, 3);
console.log('---------------------');
console.log(_pass + ' passed, ' + _fail + ' failed');
